UML = """classDiagram
    class Book {
        +String title
        +String author
        +int pages
        +summary() String
        +is_long() bool
    }
"""


class Book:
    def __init__(self, title, author, pages):
        self.title = title
        self.author = author
        self.pages = pages

    def summary(self):
        return f"{self.title} by {self.author} ({self.pages} pages)"

    def is_long(self):
        return self.pages > 300


